class Solution {
  public boolean hasMatch(String s, String p) {
    int star = p.indexOf('*');
    String prefix = p.substring(0, star), suffix = p.substring(star + 1);
    int start = s.indexOf(prefix); // earliest prefix leaves the most room for the suffix
    return start >= 0 && s.indexOf(suffix, start + prefix.length()) >= 0;
  }
}
